object NewBalanceChapter1Part3 {
    val quests = listOf(
        Quest("CH1-089",1,89,"Matteo's Tools",category="Khorinis - Craftsmen's Quarter",giver = "Matteo",location="Khorinis - Craftsmen's Quarter",prerequisites="Begin in Chapter 1 after Masters' Approval while Becoming an Apprentice is still open; the tools cannot normally be recovered until Chapter 2 after A Gift for Hanna.",summary="Recover Matteo's stolen jewelry-casting tools from the thieves' island cache after freeing Hanna.",walkthroughSteps=listOf("After gaining the masters' trust, ask Matteo what he could teach you; he explains his lost jewelry-casting tools.","Progress A Gift for Hanna in Chapter 2 until Hanna is freed from prison and gives you the cache key.","Visit the small island outside Khorinis where the thieves hid their valuables.","Unlock the cache chest and recover Matteo's casting mould.","Return the tools to Matteo and choose between gold, an Embarla Firgasto potion or learning jewelry crafting."),reward="1,000 XP and your choice of 5,000 gold, an Embarla Firgasto potion or jewelry-crafting instruction.",warnings="Catalogue placement is by quest start; completion requires Chapter 2. Source: https://rpgrussia.com/threads/instrumenty-matteo.67235/",searchTags=listOf("matteo's tools","khorinis - craftsmen's quarter","local quest giver in khorinis - craftsmen's quarter")),
